import*as Domain from'./meu-tempo-domain.mjs?v=1';
import*as Storage from'./meu-tempo-storage.mjs';
import{recordWaterTrackerLog,WATER_TRACKER_ITEM_ID}from'./water-reminder.mjs?v=6';

let root,notify=()=>{},setBrowserTitle=()=>{},data=null,tab='daily',historyMode='comparison',selectedDate=Domain.localDate(),historyStart=Domain.shiftDate(selectedDate,-13),historyEnd=selectedDate,historyCategory='all',historyItem='all',historyProductive='all',dailyCategoryFilter='all',editingItemId=null,mounted=false,dailyTableScrollTop=0;
const TIME_ENTRY_TOAST_DURATION_MS=7200;
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const fmtNumber=(value,digits=0)=>new Intl.NumberFormat('pt-BR',{minimumFractionDigits:digits,maximumFractionDigits:digits}).format(Number(value)||0);
const dateLabel=Domain.formatBrazilianDate;
const itemMap=()=>new Map(data.items.map(item=>[item.id,item]));
const categoryMap=()=>new Map(data.categories.map(category=>[category.id,category]));
const dayFor=date=>data.days.find(day=>day.date===date)||{date,lastRecordedTime:null,output:'',observations:''};
const entriesFor=date=>data.entries.filter(entry=>entry.date===date);
const button=(label,attrs='')=>`<button class="btn" type="button" ${attrs}>${label}</button>`;
const dateField=(id,iso,extraClass='',ariaLabel='')=>{const classes=['time-input','hub-input-surface',extraClass].filter(Boolean).join(' '),aria=ariaLabel?` aria-label="${esc(ariaLabel)}"`:'';return`<input id="${id}" class="${classes}" type="text" inputmode="numeric" autocomplete="off" placeholder="dd/mm/aaaa" value="${dateLabel(iso)}" data-iso="${iso||''}"${aria}>`};
export function productiveTotalHighlightClass(minutes){const total=Number(minutes);if(minutes==null||!Number.isFinite(total)||total<0)return'';return total<3.5*60?'time-under-three-and-a-half-hours':total>8*60?'time-over-eight-hours':''}
export function alcoholHistoryHighlightClass(item,value){return item?.id==='item-alcool'&&Domain.booleanHistoryValue(item,value)==='Sim'?'time-alcohol-yes':''}
export function refrigeranteHistoryHighlightClass(item,value){return item?.id==='item-refrigerante'&&Domain.booleanHistoryValue(item,value)==='Sim'?'time-refrigerante-yes':''}
export function verdeHorarioHistoryHighlightClass(item,value){return item?.id==='item-verde-horario'&&Domain.booleanHistoryValue(item,value)==='Sim'?'time-verde-horario-yes':''}
export function moveVisibleItemInOrder(items,itemId,direction,visibleIds=items.map(item=>item.id)){
  const step=Math.sign(Number(direction)),visibleIndex=visibleIds.indexOf(itemId),targetId=visibleIds[visibleIndex+step];
  if(!step||visibleIndex<0||!targetId)return null;
  const ids=items.map(item=>item.id),from=ids.indexOf(itemId),to=ids.indexOf(targetId);
  if(from<0||to<0)return null;
  [ids[from],ids[to]]=[ids[to],ids[from]];
  return ids;
}

function bindDateField(id,current,onValid,{min,max}={}){
  const input=root.querySelector(`#${id}`);if(!input)return;
  const commit=()=>{try{const iso=Domain.parseBrazilianDate(input.value);if(min&&iso<min||max&&iso>max)throw new Error(`Informe uma data entre ${dateLabel(min)} e ${dateLabel(max)}.`);onValid(iso)}catch(error){input.value=dateLabel(input.dataset.iso||current);setMessage(error.message,true)}};
  input.onchange=commit;
  input.onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();input.blur()}}
}

function rememberDailyTableScroll(){const tableWrap=tab==='daily'?root?.querySelector('.time-table-wrap'):null;if(tableWrap)dailyTableScrollTop=tableWrap.scrollTop}
async function refresh(message,toastOptions={}){rememberDailyTableScroll();data=await Storage.snapshot();render();if(message)notify(message,false,toastOptions.duration,toastOptions.highlight)}
function setMessage(message,error=false){const el=root.querySelector('#timeMessage');if(!el)return;el.textContent=message||'';el.className=error?'time-error':'time-success'}
function viewTabs(){return`<div class="time-tabs" role="tablist"><button data-tab="daily" class="${tab==='daily'?'active':''}">Diário</button><button data-tab="history" class="${tab==='history'?'active':''}">Histórico</button><button data-tab="analysis" class="${tab==='analysis'?'active':''}">Análises</button><button data-tab="config" class="secondary ${tab==='config'?'active':''}">Configurar</button></div>`}
function shell(content){root.innerHTML=`<div class="time-shell">${viewTabs()}<div id="timeMessage"></div>${content}</div>${editingItemId?renderItemEditDialog(itemMap().get(editingItemId)):''}<dialog id="timeCellModal" class="time-cell-modal"></dialog>`;bindCommon();if(editingItemId)bindItemEditDialog()}
function bindCommon(){root.querySelectorAll('[data-tab]').forEach(el=>el.onclick=()=>{tab=el.dataset.tab;render()})}

function dailyView(){
  if(dailyCategoryFilter!=='all'&&!data.categories.some(category=>category.id===dailyCategoryFilter&&category.active))dailyCategoryFilter='all';
  const day=dayFor(selectedDate),daily=Domain.aggregateDay(data.entries,selectedDate),preWorkMinutes=Domain.totalPreWorkDuration(data.entries,selectedDate),categories=categoryMap(),items=data.items.filter(item=>item.active),today=Domain.localDate();
  const topActivities=items.filter(item=>item.type==='duration'&&item.showInCharts&&item.id!=='item-dormindo').map(item=>({label:item.name,value:daily.byItem.get(item.id)?.minutes||0})).filter(item=>item.value>0).sort((a,b)=>b.value-a.value).slice(0,8);
  shell(`<div class="time-daily-summary"><div class="time-date-controls"><div class="hub-month-navigation" role="group" aria-label="Navegação por dia"><button id="timePreviousDay" class="btn hub-month-arrow" type="button" data-shift="-1" aria-label="Dia anterior" title="Dia anterior">‹</button>${dateField('timeDate',selectedDate,'hub-month-date-entry hub-month-label','Data selecionada')}<button id="timeNextDay" class="btn hub-month-arrow" type="button" data-shift="1" aria-label="Próximo dia" title="Próximo dia">›</button></div><button id="timeToday" class="btn hub-month-current" type="button">Hoje</button></div><div class="time-kpis"><div class="time-kpi"><span>Tempo produtivo</span><strong>${Domain.formatDuration(daily.productiveMinutes)}</strong></div><div class="time-kpi"><span>Tempo total registrado</span><strong>${Domain.formatDuration(daily.totalMinutes)}</strong></div><div class="time-kpi"><span>Percentual produtivo</span><strong>${fmtNumber(daily.productivePercent,1)}%</strong></div><div class="time-kpi"><span>Tempo até começar a trabalhar</span><strong>${Domain.formatDuration(preWorkMinutes)}</strong></div></div><div class="time-actions">${button('Desfazer último','id="timeUndo"')}</div></div><div class="time-grid"><section class="card time-panel"><div class="time-panel-head"><div><h2>Lançamento rápido</h2><p>Digite a duração e pressione Enter, ou complete automaticamente até o horário atual.</p></div><select id="dailyCategory" class="time-select"><option value="all" ${dailyCategoryFilter==='all'?'selected':''}>Todas as categorias</option>${data.categories.filter(x=>x.active).map(category=>`<option value="${category.id}" ${category.id===dailyCategoryFilter?'selected':''}>${esc(category.name)}</option>`).join('')}</select></div><div class="time-table-wrap time-daily-table-wrap"><table class="time-table"><thead><tr><th>Atividade</th><th>Categoria</th><th>Produtiva</th><th>Total hoje</th><th>Registrar até agora</th><th>Adicionar manualmente</th><th>Remover manualmente</th><th>Ação</th></tr></thead><tbody>${items.map(item=>dailyItemRow(item,categories,daily,today)).join('')}</tbody></table></div></section><aside class="time-notes">${barChart('Top atividades do dia',topActivities,true,'time-daily-chart')}<section class="card time-panel"><h3>Output do dia</h3><textarea id="dayOutput" class="time-textarea time-output-textarea" placeholder="O que foi entregue hoje?">${esc(day.output||'')}</textarea><h3>Observações</h3><textarea id="dayObservations" class="time-textarea" placeholder="Notas livres sobre o dia">${esc(day.observations||'')}</textarea><div style="margin-top:8px">${button('Salvar dia','id="saveDay" class="btn primary"')}</div></section>${dailyLaunchHistory(data.entries,selectedDate)}</aside></div>`);
  bindDaily(day);
}

function dailyLaunchHistory(entries,date){
  const rows=Domain.dailyLaunchHistory(entries,date,WATER_TRACKER_ITEM_ID),items=itemMap();
  const hasLegacyExcelEntries=entries.some(entry=>entry?.date===date&&entry?.source==='excel_import'&&(entry?.type==='duration'||entry?.itemId===WATER_TRACKER_ITEM_ID&&entry?.type==='number'));
  return`<section class="card time-panel time-daily-launch-history"><div class="time-panel-head"><div><h2>Histórico de lançamentos do dia</h2><p>${rows.length} ${rows.length===1?'lançamento':'lançamentos'} · mais recentes primeiro</p></div></div>${rows.length?`<div class="time-table-wrap time-daily-launch-history-wrap"><table class="time-table"><thead><tr><th>Atividade</th><th>Registro</th><th>Lançado às</th></tr></thead><tbody>${rows.map(entry=>{const item=items.get(entry.itemId),waterEntry=entry.itemId===WATER_TRACKER_ITEM_ID&&entry.type==='number',amount=Number(entry.value),display=entry.type==='duration'?Domain.formatDuration(entry.minutes):waterEntry&&Number.isFinite(amount)?`${fmtNumber(amount,amount%1?1:0)} ml`:'—';return`<tr><td class="activity">${esc(item?.name||entry.itemNameSnapshot||'Item removido')}</td><td>${display}</td><td>${formatLaunchTime(entry.createdAt)}</td></tr>`}).join('')}</tbody></table></div>`:'<p class="time-daily-launch-empty">Nenhum lançamento manual de duração ou água nesta data.</p>'}${hasLegacyExcelEntries?'<p class="time-daily-launch-note">Há lançamentos antigos do Excel nesta data. Eles não aparecem aqui porque não têm o horário original.</p>':''}</section>`;
}

function formatLaunchTime(value){const date=value?new Date(value):null;return date&&Number.isFinite(date.getTime())?new Intl.DateTimeFormat('pt-BR',{hour:'2-digit',minute:'2-digit'}).format(date):'—'}

function dailyItemRow(item,categories,daily,today){
  const cell=daily.byItem.get(item.id),total=item.type==='duration'?Domain.formatDuration(cell?.minutes||0):formatValues(item,cell?.values||[]),totalIsZero=item.type==='duration'&&Number(cell?.minutes||0)===0,category=categories.get(item.categoryId)?.name||'Sem categoria',disabled=selectedDate!==today?'disabled title="Registrar até agora está disponível somente no dia atual."':'';
  let control='';
  if(item.type==='duration')control=`<input class="time-input quick-input" data-manual="${item.id}" inputmode="numeric" placeholder="ex.: 110" aria-label="Duração rápida de ${esc(item.name)}"><button class="time-mini" data-interval="${item.id}">Intervalo</button>`;
  else if(item.type==='boolean')control=`<select class="time-select value-input" data-value="${item.id}"><option value="">Escolha</option><option value="1">Sim</option><option value="0">Não</option></select>`;
  else if(Domain.SYMPTOM_SCALE_ITEM_IDS.includes(item.id))control=`<select class="time-select value-input" data-value="${item.id}"><option value="">Escolha</option>${Domain.SYMPTOM_SCALE_OPTIONS.map(option=>`<option value="${option.value}">${option.label}</option>`).join('')}</select>`;
  else if(item.type==='text')control=`<input class="time-input value-input" data-value="${item.id}" placeholder="Texto">`;
  else if(item.type==='time')control=`<input class="time-input value-input" data-value="${item.id}" type="time">`;
  else if(item.inputUnit==='water_unit')control=`<input class="time-input value-input" data-value="${item.id}" type="text" inputmode="decimal" placeholder="copos (+/-)" aria-label="Copos de água: use valor negativo para corrigir um lançamento">`;
  else control=`<input class="time-input value-input" data-value="${item.id}" inputmode="decimal" placeholder="valor">`;
  const productive=item.type==='duration'?item.id===Domain.PARTIALLY_PRODUCTIVE_ITEM_ID?`<span title="10% de cada lançamento entra no tempo produtivo">10%</span>`:`<label class="time-productive-check"><input type="checkbox" data-productive="${item.id}" ${item.productive?'checked':''}><span>${item.productive?'Sim':'Não'}</span></label>`:'—',removeControl=item.type==='duration'?`<input class="time-input quick-input" data-remove="${item.id}" inputmode="numeric" placeholder="ex.: 30" aria-label="Remover duração de ${esc(item.name)}">`:'—';
  return`<tr class="${item.productive?'time-productive-row ':''}${item.id==='item-alcool'?'time-behavior-start':''}" data-category="${esc(item.categoryId)}" data-item-id="${esc(item.id)}"><td class="activity">${esc(item.name)}</td><td>${esc(category)}</td><td>${productive}</td><td class="${totalIsZero?'time-total-zero':''}">${total}</td><td>${item.type==='duration'?`<button class="time-mini" data-until="${esc(item.id)}" ${disabled}>Até agora</button>`:'—'}</td><td><div class="time-inline">${control}${item.type!=='duration'?`<button class="time-mini" data-add-value="${esc(item.id)}">Adicionar</button>`:''}</div></td><td>${removeControl}</td><td class="time-row-actions"><div class="time-row-actions-buttons"><button class="time-mini" type="button" data-move-item="${esc(item.id)}" data-direction="-1" aria-label="Mover ${esc(item.name)} para cima" title="Mover para cima">↑</button><button class="time-mini" type="button" data-move-item="${esc(item.id)}" data-direction="1" aria-label="Mover ${esc(item.name)} para baixo" title="Mover para baixo">↓</button></div></td></tr>`;
}

function formatValues(item,values){if(!values.length)return'—';const value=values.at(-1);if(item.type==='boolean')return value?'Sim':'Não';if(Domain.symptomScaleHistoryValue(item,value))return Domain.symptomScaleHistoryValue(item,value);if(item.type==='number'&&item.unit==='ml')return`${fmtNumber(values.reduce((a,b)=>a+Number(b||0),0))} ml`;if(item.type==='number'||item.type==='scale')return fmtNumber(value,Number(value)%1?1:0);return esc(value)}
function historyValue(item,value,digits=1){return Domain.booleanHistoryValue(item,value)??Domain.symptomScaleHistoryValue(item,value)??fmtNumber(value,digits)}
function entryCard(entry,items){const item=items.find(x=>x.id===entry.itemId)||{name:entry.itemNameSnapshot||'Item removido',type:entry.type},value=entry.type==='duration'?`${entry.start&&entry.end?`${entry.start} → ${entry.end} · `:''}${Domain.formatDuration(entry.minutes)}`:item.type==='number'&&item.unit==='ml'?`${fmtNumber(entry.value)} ml`:entry.type==='boolean'?(entry.value?'Sim':'Não'):Domain.symptomScaleHistoryValue(item,entry.value)??String(entry.value??entry.text??'—');return`<div class="time-entry"><div><strong>${esc(item.name)}</strong><small>${esc(value)} · ${Domain.productivityLabel(entry)} · <span class="time-source">${esc(entry.source)}</span></small></div><div class="time-entry-actions"><button class="time-mini" data-edit-entry="${entry.id}">Editar</button><button class="time-mini danger" data-delete-entry="${entry.id}">Excluir</button></div></div>`}

function bindDaily(day){
  root.querySelectorAll('[data-shift]').forEach(el=>el.onclick=()=>{selectedDate=Domain.shiftDate(selectedDate,Number(el.dataset.shift));render()});bindDateField('timeDate',selectedDate,iso=>{selectedDate=iso;render()});root.querySelector('#timeToday').onclick=()=>{selectedDate=Domain.localDate();render()};
  root.querySelector('#dailyCategory').onchange=e=>{dailyCategoryFilter=e.target.value;root.querySelectorAll('tbody tr[data-category]').forEach(row=>row.classList.toggle('hidden',dailyCategoryFilter!=='all'&&row.dataset.category!==dailyCategoryFilter));updateDailyMoveControls()};
  root.querySelectorAll('[data-move-item]').forEach(button=>button.onclick=()=>moveDailyItem(button.dataset.moveItem,Number(button.dataset.direction)));
  root.querySelectorAll('tbody tr[data-category]').forEach(row=>row.classList.toggle('hidden',dailyCategoryFilter!=='all'&&row.dataset.category!==dailyCategoryFilter));updateDailyMoveControls();
  root.querySelectorAll('input[data-manual],input[data-value],input[data-remove]').forEach(input=>input.onkeydown=e=>submitManualOnEnter(e,input));
  root.querySelectorAll('[data-productive]').forEach(input=>input.onchange=()=>setActivityProductivity(input.dataset.productive,input.checked));
  root.querySelectorAll('[data-interval]').forEach(button=>button.onclick=()=>addInterval(button.dataset.interval));
  root.querySelectorAll('[data-until]').forEach(button=>button.onclick=()=>addUntilNow(button.dataset.until));
  root.querySelectorAll('[data-add-value]').forEach(button=>button.onclick=()=>addValue(button.dataset.addValue));
  root.querySelectorAll('[data-delete-entry]').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir este lançamento?'))return;await Storage.deleteEntry(button.dataset.deleteEntry);await refresh('Lançamento excluído.')});
  root.querySelectorAll('[data-edit-entry]').forEach(button=>button.onclick=()=>editEntry(button.dataset.editEntry));
  root.querySelector('#timeUndo').onclick=async()=>{const removed=await Storage.undoLast(selectedDate);await refresh(removed?'Último lançamento desfeito.':'Não há lançamento manual para desfazer.')};
  root.querySelector('#saveDay').onclick=async()=>{await Storage.saveDay({...day,date:selectedDate,lastRecordedTime:day.lastRecordedTime||null,output:root.querySelector('#dayOutput').value,observations:root.querySelector('#dayObservations').value});await refresh('Dados do dia salvos.')};
}

function updateDailyMoveControls(){
  const rows=[...root.querySelectorAll('tbody tr[data-item-id]')].filter(row=>!row.classList.contains('hidden'));
  rows.forEach((row,index)=>row.querySelectorAll('[data-move-item]').forEach(button=>{button.disabled=button.dataset.direction==='-1'?index===0:index===rows.length-1}));
}

async function moveDailyItem(itemId,direction){
  try{
    const visibleIds=[...root.querySelectorAll('tbody tr[data-item-id]')].filter(row=>!row.classList.contains('hidden')).map(row=>row.dataset.itemId),orderedItems=[...data.items],orderedIds=moveVisibleItemInOrder(orderedItems,itemId,direction,visibleIds);
    if(!orderedIds)return;
    await Storage.reorderItems(orderedIds);
    await refresh('Ordem das atividades atualizada.');
  }catch(error){setMessage(error.message,true)}
}

async function submitManualOnEnter(event,input){if(event.key!=='Enter'||event.isComposing||event.repeat)return;event.preventDefault();if(input.dataset.submitting==='true')return;input.dataset.submitting='true';input.disabled=true;try{if(input.dataset.remove)await removeManualDuration(input.dataset.remove,input.value);else if(input.dataset.manual)await addManualDuration(input.dataset.manual,input.value);else await addValue(input.dataset.value)}finally{if(input.isConnected){input.disabled=false;delete input.dataset.submitting}}}
async function setActivityProductivity(itemId,productive){try{const item=itemMap().get(itemId),result=await Storage.setItemProductivity(item,productive);await refresh(`${item.name}: ${productive?'produtiva':'não produtiva'} em todos os dias; ${result.updatedEntries} lançamento(s) atualizado(s).`)}catch(error){setMessage(error.message,true)}}
async function addManualDuration(itemId,raw){try{const item=itemMap().get(itemId),minutes=Domain.parseQuickDuration(raw),formattedDuration=Domain.formatDuration(minutes);await Storage.saveEntry({date:selectedDate,itemId,type:'duration',minutes,start:null,end:null,source:'manual',...Domain.snapshotFor(item)});await refresh(`${item.name}: ${formattedDuration} registrado.`,{duration:TIME_ENTRY_TOAST_DURATION_MS,highlight:formattedDuration})}catch(error){setMessage(error.message,true)}}
async function removeManualDuration(itemId,raw){try{const item=itemMap().get(itemId),minutes=Domain.parseQuickDuration(raw);await Storage.removeDuration(selectedDate,itemId,minutes);await refresh(`${item.name}: ${Domain.formatDuration(minutes)} removido.`)}catch(error){setMessage(error.message,true)}}
async function addInterval(itemId){try{const item=itemMap().get(itemId),start=prompt('Horário inicial (HH:MM):',dayFor(selectedDate).lastRecordedTime||'');if(start==null)return;const end=prompt('Horário final (HH:MM):','');if(end==null)return;const minutes=Domain.minutesBetween(start,end),formattedDuration=Domain.formatDuration(minutes);await Storage.saveEntry({date:selectedDate,itemId,type:'duration',minutes,start,end,source:'manual',...Domain.snapshotFor(item)});await Storage.saveDay({...dayFor(selectedDate),lastRecordedTime:end});await refresh(`${item.name}: intervalo de ${formattedDuration} registrado.`,{duration:TIME_ENTRY_TOAST_DURATION_MS,highlight:formattedDuration})}catch(error){setMessage(error.message,true)}}
async function addUntilNow(itemId){try{const item=itemMap().get(itemId),daily=Domain.aggregateDay(data.entries,selectedDate),now=new Date(),currentMinutes=now.getHours()*60+now.getMinutes(),interval=Domain.registeredIntervalUntil(daily.totalMinutes,currentMinutes),formattedDuration=Domain.formatDuration(interval.minutes);await Storage.saveEntry({date:selectedDate,itemId,type:'duration',minutes:interval.minutes,start:interval.start,end:interval.end,source:'registrar_ate_agora',...Domain.snapshotFor(item)});await refresh(`${item.name}: ${formattedDuration} registrado até ${interval.end}.`,{duration:TIME_ENTRY_TOAST_DURATION_MS,highlight:formattedDuration})}catch(error){setMessage(error.message,true)}}
async function addValue(itemId){try{const item=itemMap().get(itemId),input=root.querySelector(`[data-value="${CSS.escape(itemId)}"]`),raw=input.value;if(raw==='')throw new Error('Informe um valor.');let value=raw;if(item.inputUnit==='water_unit')value=Domain.waterUnitsToMl(raw,data.settings.waterUnitMl).ml;else if(item.type==='number'||item.type==='scale')value=Domain.parseLocalizedNumber(raw);else if(item.type==='boolean')value=raw==='1';await Storage.saveEntry({date:selectedDate,itemId,type:item.type,value,source:'manual',...Domain.snapshotFor(item)});if(itemId===WATER_TRACKER_ITEM_ID)recordWaterTrackerLog({itemId,value});await refresh(`${item.name} registrado.`)}catch(error){setMessage(error.message,true)}}
async function editEntry(id){const entry=data.entries.find(x=>x.id===id);if(!entry)return;try{if(entry.type==='duration'){const raw=prompt('Nova duração em formato rápido:',String(entry.minutes<60?entry.minutes:`${Math.floor(entry.minutes/60)}${String(entry.minutes%60).padStart(2,'0')}`));if(raw==null)return;entry.minutes=Domain.parseQuickDuration(raw);entry.start=null;entry.end=null}else{const raw=prompt('Novo valor:',String(entry.value??entry.text??''));if(raw==null)return;entry.value=entry.type==='number'||entry.type==='scale'?Domain.parseLocalizedNumber(raw):entry.type==='boolean'?['1','sim','true'].includes(raw.toLowerCase()):raw}await Storage.saveEntry(entry);if(entry.itemId===WATER_TRACKER_ITEM_ID)recordWaterTrackerLog({itemId:entry.itemId,value:entry.value??entry.text});await refresh('Lançamento atualizado.')}catch(error){setMessage(error.message,true)}}

function historyView(){
  const dates=Domain.dateRange(historyStart,historyEnd),categories=data.categories.filter(x=>x.active),items=data.items.filter(x=>x.active),filteredItems=items.filter(item=>(historyCategory==='all'||item.categoryId===historyCategory)&&(historyItem==='all'||item.id===historyItem)&&(historyProductive==='all'||item.id===Domain.PARTIALLY_PRODUCTIVE_ITEM_ID||String(Boolean(item.productive))===historyProductive)),filteredEntries=data.entries.filter(entry=>dates.includes(entry.date)&&filteredItems.some(item=>item.id===entry.itemId)),today=Domain.localDate(),lastSevenStart=Domain.shiftDate(today,-6),lastSevenDates=Domain.dateRange(lastSevenStart,today),workCategoryId=data.categories.find(category=>Domain.normalizedName(category.name)==='trabalho')?.id,workMinutes=workCategoryId?Domain.totalDurationForCategory(data.entries,data.items,workCategoryId,lastSevenDates):null,productiveMinutes=Domain.totalProductiveDuration(data.entries,lastSevenDates);
  shell(`<div class="time-history-summary"><div class="time-kpi time-history-kpi"><span>Tempo trabalhado · últimos 7 dias</span><strong>${workMinutes==null?'—':Domain.formatDuration(workMinutes)}</strong><small>${dateLabel(lastSevenStart)} a ${dateLabel(today)} · categoria Trabalho</small></div><div class="time-kpi time-history-kpi"><span>Tempo produtivo · últimos 7 dias</span><strong>${Domain.formatDuration(productiveMinutes)}</strong><small>${dateLabel(lastSevenStart)} a ${dateLabel(today)} · todos os lançamentos produtivos</small></div></div><div class="time-toolbar"><div class="time-history-controls"><div class="time-filter"><label>Início</label>${dateField('historyStart',historyStart)}</div><div class="time-filter"><label>Fim</label>${dateField('historyEnd',historyEnd)}</div><div class="time-filter"><label>Categoria</label><select id="historyCategory" class="time-select"><option value="all">Todas</option>${categories.map(x=>`<option value="${x.id}" ${x.id===historyCategory?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="time-filter"><label>Atividade</label><select id="historyItem" class="time-select"><option value="all">Todas</option>${items.map(x=>`<option value="${x.id}" ${x.id===historyItem?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="time-filter"><label>Produtividade</label><select id="historyProductive" class="time-select"><option value="all">Todos</option><option value="true" ${historyProductive==='true'?'selected':''}>Produtivos</option><option value="false" ${historyProductive==='false'?'selected':''}>Não produtivos</option></select></div></div><div class="time-history-subtabs"><button data-history-mode="comparison" class="${historyMode==='comparison'?'active':''}">Comparação</button><button data-history-mode="detailed" class="${historyMode==='detailed'?'active':''}">Detalhado</button><button data-history-mode="summary" class="${historyMode==='summary'?'active':''}">Resumo</button></div></div><section class="card time-panel">${historyMode==='comparison'?comparisonContent(filteredItems,filteredEntries,dates):historyMode==='detailed'?detailedContent(filteredItems,filteredEntries,dates):summaryContent(filteredItems,filteredEntries,dates)}</section>`);
  if(historyMode==='comparison')highlightConsumedRefrigeranteCells();
  bindHistory();
}

function highlightConsumedRefrigeranteCells(){
  const item=data.items.find(candidate=>candidate.id==='item-refrigerante')||{id:'item-refrigerante',type:'boolean'},consumedDates=new Set(data.entries.filter(entry=>entry.itemId===item.id&&refrigeranteHistoryHighlightClass(item,entry.value)).map(entry=>entry.date));
  root.querySelectorAll('.time-matrix td[data-cell-item="item-refrigerante"]').forEach(cell=>{if(consumedDates.has(cell.dataset.cellDate))cell.classList.add('time-refrigerante-yes')});
}

function comparisonContent(items,entries,dates){const matrix=Domain.comparisonMatrix(items,entries,dates),hasDuration=matrix.rows.some(row=>row.item.type==='duration'),firstBehavior=matrix.rows.findIndex(row=>row.item.type!=='duration'),productiveAverage=matrix.averages.productiveMinutes,totalAverage=matrix.averages.totalMinutes,hasRecordedDay=matrix.foot.some(day=>day.entries.length>0),averageCell=value=>value==null?'—':Domain.formatDuration(value),alcoholItem=items.find(item=>item.id==='item-alcool')||{id:'item-alcool',type:'boolean'},alcoholDates=new Set(data.entries.filter(entry=>entry.itemId==='item-alcool'&&Domain.booleanHistoryValue(alcoholItem,entry.value)==='Sim').map(entry=>entry.date));return`<div class="time-panel-head"><div><h2>Comparação por atividade</h2><p>Totais por dia; clique em uma célula para ver os lançamentos.</p></div><span class="tag">${dates.length} dia(s)</span></div><div class="time-matrix-wrap"><table class="time-matrix"><thead><tr><th>Atividade</th>${dates.map(date=>`<th class="${alcoholDates.has(date)?'time-alcohol-day':''}">${dateLabel(date)}</th>`).join('')}<th>Média</th></tr></thead><tbody>${matrix.rows.map((row,index)=>`<tr class="${row.item.productive?'time-productive-row ':''}${hasDuration&&index===firstBehavior?'time-behavior-start':''}"><td>${esc(row.item.name)}</td>${row.cells.map((cell,cellIndex)=>`<td class="${cell.entries.length?'has-value ':''}${cell.values.some(value=>alcoholHistoryHighlightClass(row.item,value))?'time-alcohol-yes':cell.values.some(value=>verdeHorarioHistoryHighlightClass(row.item,value))?'time-verde-horario-yes':''}" data-cell-item="${row.item.id}" data-cell-date="${dates[cellIndex]}">${row.item.type==='duration'?(cell.entries.length?Domain.formatDuration(cell.minutes):'—'):cell.values.length?historyValue(row.item,cell.values.map(Number).filter(Number.isFinite).reduce((a,b)=>a+b,0),1):'—'}</td>`).join('')}<td>${row.item.type==='duration'?Domain.formatDuration(row.average):historyValue(row.item,row.average,1)}</td></tr>`).join('')}<tr><td><strong>Tempo produtivo</strong></td>${matrix.foot.map(x=>`<td class="${productiveTotalHighlightClass(x.entries.length?x.productiveMinutes:null)}"><strong>${Domain.formatDuration(x.productiveMinutes)}</strong></td>`).join('')}<td class="${productiveTotalHighlightClass(hasRecordedDay?productiveAverage:null)}"><strong>${averageCell(productiveAverage)}</strong></td></tr><tr><td><strong>Tempo total</strong></td>${matrix.foot.map(x=>`<td><strong>${Domain.formatDuration(x.totalMinutes)}</strong></td>`).join('')}<td><strong>${averageCell(totalAverage)}</strong></td></tr></tbody></table></div>`}
function detailedContent(items,entries,dates){const selected=dates.includes(selectedDate)?selectedDate:dates.at(-1),rows=entries.filter(x=>x.date===selected),itemsById=new Map(items.map(x=>[x.id,x]));return`<div class="time-panel-head"><div><h2>Detalhamento de ${dateLabel(selected)}</h2><p>Registros em ordem cronológica.</p></div>${dateField('detailedDate',selected)}</div><div class="time-table-wrap time-history-table-wrap"><table class="time-table"><thead><tr><th>Início</th><th>Fim</th><th>Duração / valor</th><th>Atividade</th><th>Categoria</th><th>Produtivo</th><th>Origem</th><th>Ações</th></tr></thead><tbody>${rows.length?rows.map(entry=>{const item=itemsById.get(entry.itemId)||{id:entry.itemId,name:entry.itemNameSnapshot,type:entry.type},category=categoryMap().get(entry.categoryIdSnapshot)?.name||'—',value=entry.type==='duration'?Domain.formatDuration(entry.minutes):item.type==='boolean'||Domain.SYMPTOM_SCALE_ITEM_IDS.includes(item.id)?historyValue(item,entry.value):String(entry.value??entry.text??'—');return`<tr class="${entry.productiveSnapshot?'time-productive-row ':''}${alcoholHistoryHighlightClass(item,entry.value)}"><td>${entry.start||'—'}</td><td>${entry.end||'—'}</td><td>${esc(value)}</td><td>${esc(item.name)}</td><td>${esc(category)}</td><td>${Domain.productivityLabel(entry)}</td><td>${esc(entry.source)}</td><td><button class="time-mini" data-edit-entry="${entry.id}">Editar</button> <button class="time-mini danger" data-delete-entry="${entry.id}">Excluir</button></td></tr>`}).join(''):'<tr><td colspan="8" class="time-empty">Nenhum registro no dia.</td></tr>'}</tbody></table></div>`}
function summaryContent(items,entries,dates){return`<div class="time-panel-head"><div><h2>Resumo dos dias</h2><p>Indicadores e output diário do período.</p></div></div><div class="time-summary-grid">${dates.map(date=>{const day=Domain.aggregateDay(entries,date),meta=dayFor(date),sleep=day.byItem.get('item-dormindo')?.minutes||0,water=day.byItem.get('item-agua')?.values?.map(Number).filter(Number.isFinite).reduce((a,b)=>a+b,0)||0,clarity=day.byItem.get('item-clareza')?.values?.at(-1);return`<div class="card time-day-card"><h3>${dateLabel(date)}</h3><dl><dt>Tempo produtivo</dt><dd>${Domain.formatDuration(day.productiveMinutes)}</dd><dt>Tempo total</dt><dd>${Domain.formatDuration(day.totalMinutes)}</dd><dt>% produtivo</dt><dd>${fmtNumber(day.productivePercent,1)}%</dd><dt>Média em Dormindo</dt><dd>${Domain.formatDuration(sleep)}</dd><dt>Água</dt><dd>${fmtNumber(water)} ml</dd><dt>Clareza mental</dt><dd>${clarity==null?'—':fmtNumber(clarity,1)}</dd></dl>${meta.output?`<p class="muted">${esc(meta.output)}</p>`:''}</div>`}).join('')}</div>`}
function bindHistory(){bindDateField('historyStart',historyStart,iso=>{historyStart=iso;render()});bindDateField('historyEnd',historyEnd,iso=>{historyEnd=iso;render()});root.querySelector('#historyCategory').onchange=e=>{historyCategory=e.target.value;render()};root.querySelector('#historyItem').onchange=e=>{historyItem=e.target.value;render()};root.querySelector('#historyProductive').onchange=e=>{historyProductive=e.target.value;render()};root.querySelectorAll('[data-history-mode]').forEach(el=>el.onclick=()=>{historyMode=el.dataset.historyMode;render()});bindDateField('detailedDate',selectedDate,iso=>{selectedDate=iso;render()},{min:historyStart,max:historyEnd});root.querySelectorAll('[data-cell-item]').forEach(cell=>cell.onclick=()=>openCell(cell.dataset.cellItem,cell.dataset.cellDate));root.querySelectorAll('[data-edit-entry]').forEach(button=>button.onclick=()=>editEntry(button.dataset.editEntry));root.querySelectorAll('[data-delete-entry]').forEach(button=>button.onclick=async()=>{if(confirm('Excluir este lançamento?')){await Storage.deleteEntry(button.dataset.deleteEntry);await refresh('Lançamento excluído.')}})}
function openCell(itemId,date){const item=itemMap().get(itemId),entries=data.entries.filter(x=>x.itemId===itemId&&x.date===date),dialog=root.querySelector('#timeCellModal');dialog.innerHTML=`<div class="time-modal-head" style="padding:16px;border-bottom:1px solid var(--line)"><div><h2>${esc(item?.name||'Atividade')}</h2><p class="muted">${dateLabel(date)}</p></div><button class="time-mini" id="closeCell">Fechar</button></div><div class="time-cell-body">${entries.length?entries.map(entry=>entryCard(entry,[item])).join(''):'<div class="time-empty">Sem registros.</div>'}${entries.some(x=>x.source==='excel_import')?'<p class="muted">Origem: Excel · horários não disponíveis quando não existiam na planilha.</p>':''}</div>`;dialog.showModal();dialog.querySelector('#closeCell').onclick=()=>dialog.close();dialog.querySelectorAll('[data-edit-entry]').forEach(button=>button.onclick=()=>{dialog.close();editEntry(button.dataset.editEntry)});dialog.querySelectorAll('[data-delete-entry]').forEach(button=>button.onclick=async()=>{dialog.close();if(confirm('Excluir este lançamento?')){await Storage.deleteEntry(button.dataset.deleteEntry);await refresh('Lançamento excluído.')}})}

function analysisView(){
 const dates=Domain.dateRange(historyStart,historyEnd),entries=data.entries.filter(x=>dates.includes(x.date)),items=data.items.filter(x=>x.active&&x.showInCharts&&x.id!=='item-dormindo'),categories=categoryMap(),categoryTotals=new Map(),itemTotals=new Map();
 for(const entry of entries)if(entry.type==='duration'){
  const item=itemMap().get(entry.itemId),minutes=Number(entry.minutes)||0,category=item?.categoryId||entry.categoryIdSnapshot;
  if(entry.itemId!=='item-dormindo'){
   categoryTotals.set(category,(categoryTotals.get(category)||0)+minutes);
   itemTotals.set(entry.itemId,(itemTotals.get(entry.itemId)||0)+minutes)
  }
 }
 const daily=dates.map(date=>Domain.aggregateDay(entries,date)),selected=itemMap().get(historyItem==='all'?items.find(x=>x.type==='duration')?.id:historyItem),evolution=dates.map(date=>({date,value:selected?.type==='duration'?Domain.aggregateDay(entries.filter(x=>x.itemId===selected.id),date).byItem.get(selected.id)?.minutes||0:entries.filter(x=>x.itemId===selected?.id&&x.date===date).map(x=>Number(x.value)).filter(Number.isFinite).at(-1)||0}));
 shell(`<div class="time-toolbar"><div class="time-date-controls"><div class="time-field"><label>Início</label>${dateField('analysisStart',historyStart)}</div><div class="time-field"><label>Fim</label>${dateField('analysisEnd',historyEnd)}</div><div class="time-field"><label>Item para evolução</label><select id="analysisItem" class="time-select">${items.map(x=>`<option value="${x.id}" ${x.id===selected?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></div></div><div class="time-charts">${barChart('Tempo por categoria',[...categoryTotals].map(([id,value])=>({label:categories.get(id)?.name||'Sem categoria',value})),true)}${barChart('Tempo produtivo por dia',daily.map(x=>({label:dateLabel(x.date),value:x.productiveMinutes})),true)}${barChart(`Evolução · ${selected?.name||'Selecione um item'}`,evolution.map(x=>({label:dateLabel(x.date),value:x.value})),selected?.type==='duration')}${barChart('Top atividades do período',[...itemTotals].map(([id,value])=>({label:itemMap().get(id)?.name||id,value})).sort((a,b)=>b.value-a.value).slice(0,8),true)}</div>`);
 bindDateField('analysisStart',historyStart,iso=>{historyStart=iso;render()});
 bindDateField('analysisEnd',historyEnd,iso=>{historyEnd=iso;render()});
 root.querySelector('#analysisItem').onchange=e=>{historyItem=e.target.value;render()}
}
function barChart(title,rows,duration=false,extraClass=''){const max=Math.max(1,...rows.map(x=>Number(x.value)||0));return`<section class="card time-chart ${extraClass}"><h3>${esc(title)}</h3>${rows.length?rows.map(row=>`<div class="time-bar-row"><span title="${esc(row.label)}">${esc(row.label)}</span><div class="time-bar-track"><div class="time-bar-fill" style="width:${(Number(row.value)||0)/max*100}%"></div></div><strong>${duration?Domain.formatDuration(row.value):fmtNumber(row.value,1)}</strong></div>`).join(''):`<div class="time-empty">${title==='Top atividades do dia'?'Sem atividades registradas no dia.':'Sem dados no período.'}</div>`}</section>`}

function configView(){const categories=categoryMap();shell(`<div class="time-config-grid"><section class="card time-panel"><div class="time-panel-head"><div><h2>Categorias</h2><p>Crie, renomeie ou desative categorias.</p></div></div><div class="time-inline"><input id="newCategory" class="time-input" placeholder="Nova categoria">${button('Adicionar','id="addCategory"')}</div><div class="time-config-list" style="margin-top:10px">${data.categories.map(category=>`<div class="time-config-row ${category.active?'':'inactive'}"><span>${esc(category.name)}</span><div><button class="time-mini" data-rename-category="${category.id}">Renomear</button> <button class="time-mini" data-toggle-category="${category.id}">${category.active?'Desativar':'Reativar'}</button></div></div>`).join('')}</div><hr style="border:0;border-top:1px solid var(--line);margin:14px 0"><div class="time-field"><label>Volume da unidade de água</label><div class="time-inline"><input id="waterUnitMl" class="time-input" type="number" min="1" step="1" value="${Number(data.settings.waterUnitMl)||350}"><span>ml</span>${button('Salvar','id="saveWater"')}</div></div></section><section class="card time-panel"><div class="time-panel-head"><div><h2>Itens e atividades</h2><p>A produtividade é configurável e preservada por snapshot em cada lançamento.</p></div></div><div class="time-item-form"><input id="itemName" class="time-input" placeholder="Nome"><select id="itemCategory" class="time-select">${data.categories.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select><select id="itemType" class="time-select">${Domain.ITEM_TYPES.map(type=>`<option value="${type}">${type}</option>`).join('')}</select>${button('Criar item','id="addItem"')}</div><div class="time-config-list">${data.items.map(item=>`<div class="time-config-row ${item.active?'':'inactive'}"><div><strong>${esc(item.name)}</strong><small style="display:block;color:var(--muted)">${esc(categories.get(item.categoryId)?.name||'Sem categoria')} · ${item.type} · ${item.id===Domain.PARTIALLY_PRODUCTIVE_ITEM_ID?'10% produtivo (regra fixa)':item.productive?'produtivo':'não produtivo'}</small></div><div><button class="time-mini" data-edit-item="${item.id}">Editar</button> <button class="time-mini" data-toggle-item="${item.id}">${item.active?'Desativar':'Reativar'}</button> <button class="time-mini danger" data-delete-item="${item.id}">Excluir</button></div></div>`).join('')}</div></section></div>`);bindConfig()}
function bindConfig(){root.querySelector('#addCategory').onclick=async()=>{try{await Storage.saveCategory({name:root.querySelector('#newCategory').value,order:data.categories.length*10+10});await refresh('Categoria criada.')}catch(error){setMessage(error.message,true)}};root.querySelectorAll('[data-rename-category]').forEach(button=>button.onclick=async()=>{const category=data.categories.find(x=>x.id===button.dataset.renameCategory),name=prompt('Novo nome da categoria:',category.name);if(name){await Storage.saveCategory({...category,name});await refresh('Categoria atualizada.')}});root.querySelectorAll('[data-toggle-category]').forEach(button=>button.onclick=async()=>{const category=data.categories.find(x=>x.id===button.dataset.toggleCategory);await Storage.saveCategory({...category,active:!category.active});await refresh('Categoria atualizada.')});root.querySelector('#saveWater').onclick=async()=>{try{const value=Domain.parseLocalizedNumber(root.querySelector('#waterUnitMl').value);if(value<=0)throw new Error('Informe um volume maior que zero.');await Storage.saveSetting('waterUnitMl',value);await refresh('Volume da unidade de água atualizado.')}catch(error){setMessage(error.message,true)}};root.querySelector('#addItem').onclick=async()=>{try{await Storage.saveItem({name:root.querySelector('#itemName').value,categoryId:root.querySelector('#itemCategory').value,type:root.querySelector('#itemType').value,order:data.items.length*10+10,active:true,productive:false,showInCharts:true});await refresh('Item criado.')}catch(error){setMessage(error.message,true)}};root.querySelectorAll('[data-toggle-item]').forEach(button=>button.onclick=async()=>{const item=itemMap().get(button.dataset.toggleItem);await Storage.saveItem({...item,active:!item.active});await refresh('Item atualizado.')});root.querySelectorAll('[data-delete-item]').forEach(button=>button.onclick=async()=>{if(!confirm('Excluir definitivamente este item sem histórico?'))return;try{await Storage.deleteItem(button.dataset.deleteItem);await refresh('Item excluído.')}catch(error){setMessage(error.message,true)}});root.querySelectorAll('[data-edit-item]').forEach(button=>button.onclick=()=>editItem(button.dataset.editItem))}
function editItem(id){if(!itemMap().has(id))return;editingItemId=id;render()}
function renderItemEditDialog(item){
  if(!item)return'';
  const categories=categoryMap(),typeLabels={duration:'Duração',number:'Número',scale:'Escala',boolean:'Sim / não',text:'Texto',time:'Horário'},categoryOptions=data.categories.map(category=>`<option value="${esc(category.id)}" ${category.id===item.categoryId?'selected':''}>${esc(category.name)}${category.active?'':' (inativa)'}</option>`).join(''),missingCategory=categories.has(item.categoryId)?'':`<option value="${esc(item.categoryId||'')}" selected>${item.categoryId?'Categoria não encontrada':'Sem categoria atual'}</option>`,selectedType=Domain.ITEM_TYPES.includes(item.type)?item.type:'duration',chartType=['bar','line'].includes(item.chartType)?item.chartType:'bar',aggregation=['sum','average'].includes(item.aggregation)?item.aggregation:selectedType==='duration'?'sum':'average';
  return`<dialog id="timeItemEditDialog" class="time-item-edit-modal" aria-labelledby="timeItemEditTitle"><section class="card time-panel time-item-edit-card"><div class="time-modal-head"><div><h2 id="timeItemEditTitle">Editar item ou atividade</h2><p class="muted">As alterações valem para novos lançamentos; os registros anteriores mantêm seus snapshots.</p></div><button type="button" class="time-mini" data-cancel-item-edit aria-label="Fechar edição">Fechar</button></div><form id="timeItemEditForm" novalidate><div class="time-item-edit-grid"><div class="time-field"><label for="timeEditItemName">Nome do item</label><input id="timeEditItemName" class="time-input" type="text" value="${esc(item.name)}" autocomplete="off" required></div><div class="time-field"><label for="timeEditItemCategory">Categoria</label><select id="timeEditItemCategory" class="time-select">${missingCategory}${categoryOptions}</select></div><div class="time-field"><label for="timeEditItemType">Tipo de registro</label><select id="timeEditItemType" class="time-select">${Domain.ITEM_TYPES.map(type=>`<option value="${type}" ${type===selectedType?'selected':''}>${typeLabels[type]||type}</option>`).join('')}</select></div><div class="time-field"><label for="timeEditItemOrder">Ordem na tela</label><input id="timeEditItemOrder" class="time-input" type="number" step="any" value="${esc(item.order??0)}"></div></div><div class="time-item-edit-options">${item.id===Domain.PARTIALLY_PRODUCTIVE_ITEM_ID?'<p class="time-item-edit-fixed">Este item tem produtividade fixa: 10% de cada lançamento conta como produtivo.</p>':`<label class="time-item-edit-check"><input id="timeEditItemProductive" type="checkbox" ${item.productive?'checked':''} ${selectedType==='duration'?'':'disabled'}><span>Contar a duração como tempo produtivo</span></label>`}<label class="time-item-edit-check"><input id="timeEditItemCharts" type="checkbox" ${item.showInCharts?'checked':''}><span>Exibir este item nas análises</span></label></div><div class="time-item-edit-grid time-item-edit-chart-options"><div class="time-field"><label for="timeEditItemChartType">Tipo de gráfico</label><select id="timeEditItemChartType" class="time-select" ${item.showInCharts?'':'disabled'}><option value="bar" ${chartType==='bar'?'selected':''}>Barras</option><option value="line" ${chartType==='line'?'selected':''}>Linha</option></select></div><div class="time-field"><label for="timeEditItemAggregation">Agregação</label><select id="timeEditItemAggregation" class="time-select" ${item.showInCharts?'':'disabled'}><option value="sum" ${aggregation==='sum'?'selected':''}>Soma</option><option value="average" ${aggregation==='average'?'selected':''}>Média</option></select></div></div><p id="timeItemEditError" class="time-item-edit-error" role="alert" aria-live="polite"></p><div class="time-item-edit-actions"><button type="button" class="btn" data-cancel-item-edit>Cancelar</button><button type="submit" class="btn primary">Salvar alterações</button></div></form></section></dialog>`
}
function bindItemEditDialog(){
  const dialog=root.querySelector('#timeItemEditDialog'),form=root.querySelector('#timeItemEditForm');if(!dialog||!form)return;
  const close=()=>{if(dialog.open)dialog.close();editingItemId=null;render()},showError=(message,selector)=>{root.querySelector('#timeItemEditError').textContent=message;root.querySelector(selector)?.focus()},typeSelect=root.querySelector('#timeEditItemType'),productiveInput=root.querySelector('#timeEditItemProductive'),chartsInput=root.querySelector('#timeEditItemCharts'),chartTypeSelect=root.querySelector('#timeEditItemChartType'),aggregationSelect=root.querySelector('#timeEditItemAggregation');
  dialog.addEventListener('cancel',()=>{editingItemId=null},{once:true});dialog.addEventListener('click',event=>{if(event.target===dialog)close()});root.querySelectorAll('[data-cancel-item-edit]').forEach(button=>button.addEventListener('click',close));
  typeSelect.addEventListener('change',()=>{if(productiveInput)productiveInput.disabled=typeSelect.value!=='duration'});chartsInput.addEventListener('change',()=>{chartTypeSelect.disabled=!chartsInput.checked;aggregationSelect.disabled=!chartsInput.checked});
  if(!dialog.open)dialog.showModal();root.querySelector('#timeEditItemName').focus();
  form.addEventListener('submit',async event=>{
    event.preventDefault();const item=itemMap().get(editingItemId);if(!item)return close();
    const name=root.querySelector('#timeEditItemName').value.trim(),categoryId=root.querySelector('#timeEditItemCategory').value,type=typeSelect.value,orderRaw=root.querySelector('#timeEditItemOrder').value,order=Number(orderRaw),showInCharts=chartsInput.checked,chartType=chartTypeSelect.value,aggregation=aggregationSelect.value;
    if(!name)return showError('Informe um nome para o item.','#timeEditItemName');
    if(!data.categories.some(category=>category.id===categoryId)&&categoryId!==String(item.categoryId??''))return showError('Selecione uma categoria válida.','#timeEditItemCategory');
    if(!Domain.ITEM_TYPES.includes(type))return showError('Selecione um tipo de registro válido.','#timeEditItemType');
    if(!orderRaw.trim()||!Number.isFinite(order))return showError('Informe uma ordem numérica válida.','#timeEditItemOrder');
    if(!['bar','line'].includes(chartType)||!['sum','average'].includes(aggregation))return showError('Revise as opções de análise.','#timeEditItemChartType');
    try{await Storage.saveItem({...item,name,categoryId,type,order,productive:type==='duration'&&(item.id===Domain.PARTIALLY_PRODUCTIVE_ITEM_ID?Boolean(item.productive):Boolean(productiveInput?.checked)),showInCharts,chartType,aggregation,durationMode:type==='duration'?'both':null});editingItemId=null;await refresh('Item atualizado; o histórico anterior manteve seus snapshots.')}catch(error){showError(error.message||'Não foi possível salvar o item.','#timeEditItemName')}
  });
}

function render(){if(!data)return;const titles={daily:'Diário',history:'Histórico',analysis:'Análises',config:'Configurar'};setBrowserTitle(`Meu Tempo · ${titles[tab]||'Diário'}`);tab==='daily'?dailyView():tab==='history'?historyView():tab==='analysis'?analysisView():configView()}
export async function mount(options){root=options.root;notify=options.toast||(()=>{});setBrowserTitle=options.setBrowserTitle||(()=>{});if(!root)throw new Error('Contêiner do Meu Tempo não encontrado.');if(!mounted){mounted=true;root.innerHTML='<div class="time-empty">Carregando Meu Tempo...</div>'}data=await Storage.snapshot();render()}
